-- -------------------------------------------------------------------------------------------
-- show / hide
-- -------------------------------------------------------------------------------------------
local clearCity

local function waitGround(token, x, y, z, tries, done)
    if not S.shown or S.token ~= token then return end
    local hit = processLineOfSight(x, y, z + 4.0, x, y, z - 8.0, true, false, false, true, false)
    if hit then done(true) return end
    if tries <= 0 then done(false) return end
    track(setTimer(function() waitGround(token, x, y, z, tries - 1, done) end, 300, 1))
end

-- teleport inside the city: the player is held until the collision around the destination is streamed in (the sky city is 900 m up)
local function safeTeleport(x, y, z)
    setElementPosition(localPlayer, x, y, z)
    setElementVelocity(localPlayer, 0, 0, 0)
    S.hold = true
    S.tp = (S.tp or 0) + 1
    local mine = S.tp
    setElementFrozen(localPlayer, true)
    waitGround(S.token, x, y, z, 40, function(found)
        if S.tp ~= mine then return end                                  -- a newer teleport took over
        if found then
            setElementFrozen(localPlayer, false)
            S.hold = nil
        else
            say("the ground collision is not available here yet - you stay frozen. /ncview again or /nchide.", 255, 150, 120)
        end
    end)
end

local function showCity(zoff, ax, ay, az)
    if S.shown then clearCity() end
    S.token = S.token + 1
    local token = S.token
    if ax and ay and az then S.anchor = { x = ax, y = ay, z = az } end
    S.zoff = (zoff or 0) + (S.zBias or 0)                          -- /setz trim survives hide / show
    local near = cityDist() < 600
    if near then setElementFrozen(localPlayer, true) S.hold = true end        -- hold the player in the air until the ground exists
    if not S.loaded then say("loading " .. #NC_MODELS .. " models and " .. #NC_OBJECTS .. " objects - this takes a few seconds ...") end
    loadModels(function(ok)
        if S.token ~= token then return end                                    -- hidden or shown again while the models were loading
        if not ok then
            if near then setElementFrozen(localPlayer, false) S.hold = nil end
            return
        end
        S.shown = true
        applyAtmosphere()
        startEnv()
        build(token, function()
            createRiver()
            startSprites()
            startAmbience()
            fxSet(2)
            local P = NC_POINTS.spawn
            local x, y, z = toWorld(P[1], P[2], P[3])
            if near then
                waitGround(token, x, y, z, 40, function(ok2)
                    if ok2 then
                        setElementFrozen(localPlayer, false)
                        S.hold = nil
                    else
                        say("the ground collision is not available yet - you stay frozen. /nchide returns you to the map.", 255, 150, 120)
                    end
                end)
            end
            say(S.count .. " objects.  /nchide removes it, /nctour camera tour, /ncfree free camera, /ncview <point> teleport,")
            say("/ncfx graphics, /ncquality <low-ultra>, /ncweather <preset>, /nctime <hour>, /ncdaycycle <h/min>, /ncwet <0-1|auto>, /ncexposure <0.3-4>, /ncrain <0-1>, /ncenv, /ncinfo")
        end)
    end)
end

function clearCity()
    S.token = S.token + 1                        -- cancels a show that is still loading / building
    stopEnv()
    for _, e in pairs(S.objs) do if e and isElement(e) then destroyElement(e) end end
    for _, w in pairs(S.water) do if w and isElement(w.e) then destroyElement(w.e) end end
    S.objs, S.water, S.dome, S.domeIdx = {}, {}, nil, nil
    fxStop()
    stopSprites()
    stopAmbience()
    restoreAtmosphere()
    if S.hold then setElementFrozen(localPlayer, false) S.hold = nil end
    S.shown = false
    if NC and NC.onHide then NC.onHide() end
end

addEventHandler("nc:show", resourceRoot, function(zoff, ax, ay, az) showCity(zoff, ax, ay, az) end)
addEventHandler("nc:hide", resourceRoot, function()
    local was = S.shown
    clearCity()
    if was then say("NightCity removed.") end
end)

-- /nczoff trims the height of the whole city
-- city deck height: the city ground sits at (S.anchor or CFG.ANCHOR).z + S.zoff; /setz sets it, /ncz trims it
local function cityZ()
    return (S.anchor or CFG.ANCHOR).z + S.zoff
end

local function shiftCity(dz)
    S.zoff = S.zoff + dz
    if not S.shown then return end
    for k, e in pairs(S.objs) do
        if e and isElement(e) then
            local o = NC_OBJECTS[k]
            if k ~= S.domeIdx then
                local x, y, z = toWorld(o[2], o[3], o[4])
                setElementPosition(e, x, y, z)
            end
        end
    end
    for _, w in pairs(S.water) do
        if w and isElement(w.e) then pcall(setWaterLevel, w.e, (S.anchor or CFG.ANCHOR).z + S.zoff + w.z) end
    end
end

addEventHandler("nc:zoff", resourceRoot, function(dz) shiftCity(dz) end)

addCommandHandler("setz", function(_, arg)
    local v = tonumber(arg)
    if not v then
        say("usage: /setz <height | +d | -d>   (city deck height above the map, now " .. string.format("%.0f", cityZ()) .. ")")
        return
    end
    local dz
    if arg:sub(1, 1) == "+" or arg:sub(1, 1) == "-" then
        dz = v                                                     -- relative: +100 lifts, -100 drops
    else
        dz = v - cityZ()                                           -- absolute world Z of the city deck
    end
    S.zBias = (S.zBias or 0) + dz                                  -- keeps the trim across /nchide //ncshow
    shiftCity(dz)
    if S.shown then
        say("city height " .. string.format("%.0f", cityZ()))
    else
        say("city height " .. string.format("%.0f", cityZ()) .. " (applies at the next /ncshow)")
    end
end)

-- safety net for the sky city: anyone who somehow steps off the edge is brought back to the spawn point
setTimer(function()
    if not S.shown or S.hold or not S.anchor or S.anchor.z < 300 then return end
    local px, py, pz = getElementPosition(localPlayer)
    local cx, cy, cz = toWorld(0, 0, 0)
    local dx, dy = math.abs(px - cx), math.abs(py - cy)
    local E = NC_EXTENT
    local outside = dx > (E.x1 - E.x0) / 2 + 40 or dy > (E.y1 - E.y0) / 2 + 40
    if (pz < cz - 40 and dx < 900 and dy < 900) or (outside and dx < 1100 and dy < 1100 and pz < cz + 30) then
        local P = NC_POINTS.spawn
        local x, y, z = toWorld(P[1], P[2], P[3] + 1.0)
        safeTeleport(x, y, z)
    end
end, 1000, 0)

