addCommandHandler("ncrain", function(_, arg)
    if arg == "auto" then
        NC_ENV.setRain(nil)
        if S.shown then enforceAtmosphere() say("rain: driven by the weather again") end
        return
    end
    local v = tonumber(arg)
    if not v then say("usage: /ncrain <0 .. 1 | auto>   (now " .. (NC_ENV.state.rainManual and string.format("%.2f", NC_ENV.state.rainManual) or "auto (weather)") .. ")") return end
    NC_ENV.setRain(clamp(v, 0, 1))
    if S.shown then
        enforceAtmosphere()
        say("rain " .. string.format("%.2f", NC_ENV.state.rainManual))
    end
end)

addCommandHandler("nctime", function(_, arg, minute)
    local h = tonumber(arg)
    if not h then say("usage: /nctime <hour 0-23> [minute]   (or /ncdaycycle <h/min> to let time run)") return end
    NC_ENV.setClock(h, tonumber(minute))
    if S.shown then NC_ENV.apply() say(string.format("clock %02d:%02d", math.floor(NC_ENV.state.hour), math.floor((NC_ENV.state.hour % 1) * 60))) end
end)

addCommandHandler("ncview", function(_, name)
    if not S.shown then say("the city is not shown (/ncshow).") return end
    local P = name and NC_POINTS[name]
    if not P then
        local names = {}
        for k in pairs(NC_POINTS) do names[#names + 1] = k end
        table.sort(names)
        say("usage: /ncview <" .. table.concat(names, " | ") .. ">")
        return
    end
    local x, y, z = toWorld(P[1], P[2], P[3] + 0.5)
    safeTeleport(x, y, z)
end)

addCommandHandler("ncinfo", function()
    local nobj = 0
    for _, e in pairs(S.objs) do if e and isElement(e) then nobj = nobj + 1 end end
    local px, py, pz = getElementPosition(localPlayer)
    local cx, cy, cz = toCity(px, py, pz)
    say(string.format("shown=%s  models=%d  objects=%d  water=%d  glow sprites drawn=%d  graphics=%d  shaders=%d  tunnel=%s  you: x %.0f y %.0f z %.1f (city frame)",
        tostring(S.shown), #NC_MODELS, nobj, #S.water, S.drawn, FX.mode, #FX.surfaces + (FX.sky and 1 or 0) + (FX.water and 1 or 0) + (FX.post and 1 or 0),
        tostring(inTunnel(px, py, pz)), cx, cy, cz))
    say(NC_ENV.status())
end)

