    triggerServerEvent("nc:request", resourceRoot)
end)

addEventHandler("onClientResourceStop", resourceRoot, function()
    clearCity()
    freeModels()
    for _, t in ipairs(S.timers) do if isTimer(t) then killTimer(t) end end
end)
